<script>
export const page={name:"shipment-detail",path:"/shipments/:id",title:"出貨單詳情",requires:{permissions:["fulfillment.view"]}};
</script>
<script setup>
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from "vue";
import {useRoute} from "vue-router";
import PageHeader from "@/framework/layout/PageHeader.vue";
import DataTable from "@/framework/ui/DataTable.vue";
import ShipmentFormPanel from "@/components/fulfillment/ShipmentFormPanel.vue";
import ShipmentCancelPanel from "@/components/fulfillment/ShipmentCancelPanel.vue";
import ShipmentConfirmationPanel from "@/components/fulfillment/ShipmentConfirmationPanel.vue";
import {useSessionStore} from "@/stores/session.js";
import shipment,{shipmentDocumentId,shipmentFailure} from "@/services/shipment.js";
import {timestamp} from "@/components/fulfillment/fulfillmentPresentation.js";
const route=useRoute(),session=useSessionStore(),document=ref(null),loading=ref(false),error=ref(""),summary=ref(null),tab=ref("lines"),query=ref({}),draftDirty=ref(false),commands=reactive({draft:false,confirm:false,cancel:false});let controller;
const labels={DRAFT:"草稿",SHIPPING:"出貨處理中",SHIPPED:"已出貨",CANCELLED:"已取消",REVERSING:"沖銷處理中",REVERSED:"已沖銷"},operate=computed(()=>["fulfillment.view","fulfillment.operation"].every(value=>session.permissions.includes(value)));
const lineColumns=[{name:"line",label:"行",field:"lineNo",align:"left"},{name:"sku",label:"SKU",field:"skuCode",align:"left"},{name:"name",label:"品名",field:"skuName",align:"left"},{name:"quantity",label:"本次出貨數量",field:row=>`${row.shippedBaseQuantity} ${row.baseUomCode}`,align:"right"},{name:"reversed",label:"已沖銷數量",field:row=>`${row.reversedBaseQuantity} ${row.baseUomCode}`,align:"right"}];
const issueColumns=[{name:"movement",label:"庫存異動 ID",field:"inventoryMovementId",align:"left"},{name:"sku",label:"SKU",field:"skuCode",align:"left"},{name:"bin",label:"庫位",field:"binCode",align:"left"},{name:"lot",label:"批次",field:row=>row.lotNumber||'—',align:"left"},{name:"expiry",label:"到期日",field:row=>row.expiryDate||'無到期日',align:"left"},{name:"quantity",label:"已發出數量",field:row=>`${row.issuedBaseQuantity} ${row.baseUomCode}`,align:"right"}];
const historyColumns=[{name:"seq",label:"順序",field:"sequence",align:"left"},{name:"action",label:"操作",field:"action",align:"left"},{name:"status",label:"結果狀態",field:row=>labels[row.toStatus],align:"left"},{name:"reason",label:"原因",field:"reason",align:"left"},{name:"actor",label:"操作人",field:"actorLabel",align:"left"},{name:"time",label:"時間（香港時間）",field:row=>timestamp(row.occurredAt),align:"left"}];
async function load(clear=false){controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value="";if(clear)document.value=null;
 try{const value=await shipment.getShipment(shipmentDocumentId(route.params.id),{...query.value,signal});if(!signal.aborted)document.value=value.shipment;}
 catch(cause){if(!signal.aborted){error.value=shipmentFailure(cause).message;if([401,403,404].includes(cause?.status))document.value=null;}}
 finally{if(!signal.aborted){loading.value=false;if(error.value){await nextTick();summary.value?.focus();}}}}
function first(){query.value={};return load();}
function childPage(key,value){const next={...query.value};if(value===null)delete next[key];else next[key]=value;query.value=next;return load();}
watch([()=>route.params.id,()=>session.user?.id,()=>session.permissions.join('|')],()=>{query.value={};tab.value="lines";draftDirty.value=false;Object.assign(commands,{draft:false,confirm:false,cancel:false});load(true);},{immediate:true});onBeforeUnmount(()=>controller?.abort());
</script>
<template><div><PageHeader :title="document?`出貨單 ${document.number}`:undefined" subtitle="數量取自已保存的履約工作；可用操作以目前後端資料為準。"><template #actions><q-btn flat label="返回出貨單列表" to="/shipments" /><q-btn v-if="document&&session.permissions.includes('sales.view')" flat label="查看 Sales Order" :to="`/sales/orders/${document.salesOrder.id}`" /><q-btn v-if="document" flat label="查看來源履約單" :to="`/fulfillments/${document.fulfillmentId}`" /><q-btn v-if="document?.allowedActions.includes('printDeliveryNote')" flat label="送貨單列印" :to="`/shipments/${document.id}/delivery-note/print`" /><q-btn v-if="document?.allowedActions.includes('printPackingList')" flat label="裝箱單列印" :to="{path:`/shipments/${document.id}/delivery-note/print`,query:{view:'packing'}}" /></template></PageHeader>
 <section aria-label="出貨單內容" :aria-busy="loading" class="q-px-md q-pb-md"><q-skeleton v-if="loading&&!document" type="rect" height="160px" aria-label="載入出貨單" /><div v-if="error" ref="summary" role="alert" tabindex="-1"><q-banner class="bg-warning text-dark q-mb-md">{{ error }}<template #action><q-btn flat label="重新載入出貨資料" @click="first" /></template></q-banner></div>
 <template v-if="document"><div class="row items-center q-gutter-sm"><q-badge :label="labels[document.status]" :color="document.status==='SHIPPED'?'positive':document.status==='REVERSED'?'negative':'primary'" /><span>版本 {{ document.version }}</span><q-btn flat label="重新載入出貨資料" :loading="loading" @click="first" /></div>
 <q-banner v-if="document.status==='REVERSED'" role="alert" class="bg-warning text-dark q-my-md">已沖銷，只供歷史參考。</q-banner><q-banner v-if="['SHIPPING','REVERSING'].includes(document.status)" role="status" class="bg-warning text-dark q-my-md">操作處理中，所有編輯及重複提交已停用；請查詢原事件結果。</q-banner>
 <dl class="shipment-facts"><div><dt>Sales Order／履約單</dt><dd>{{ document.salesOrder.number }}／{{ document.fulfillment.number }}</dd></div><div><dt>客戶／倉庫</dt><dd>{{ document.customer.code }} — {{ document.customer.name }}／{{ document.warehouse.code }}</dd></div><div><dt>物流商／追蹤號碼</dt><dd>{{ document.carrierName||'未填寫' }}／{{ document.trackingNumber||'未填寫' }}</dd></div><div><dt>包裹數／總重量</dt><dd>{{ document.packageCount??'未填寫' }}／{{ document.totalWeight===null?'未填寫':`${document.totalWeight} ${document.weightUom}` }}</dd></div><div><dt>出貨日期</dt><dd>{{ document.shipmentDate??'尚未出貨' }}</dd></div><div><dt>送貨地址</dt><dd v-if="document.address">{{ [document.address.name,document.address.recipientCompany,document.address.recipientName,document.address.line1,document.address.line2,document.address.line3,document.address.city,document.address.region,document.address.postalCode,document.address.countryCode].filter(Boolean).join(' · ') }}</dd><dd v-else>送貨資料不可用，請重新選擇有效地址。</dd></div><div><dt>送貨聯絡人</dt><dd v-if="document.contact">{{ [document.contact.name,document.contact.phone,document.contact.email].filter(Boolean).join(' · ')||'未選擇' }}</dd><dd v-else>未選擇或已失效</dd></div></dl><p v-if="document.notes" class="shipment-notes">{{ document.notes }}</p>
 <q-tabs v-model="tab" align="left"><q-tab name="lines" label="出貨行" /><q-tab name="issues" label="庫存發出明細" /><q-tab name="history" label="狀態歷史" /></q-tabs>
 <section v-if="tab==='lines'" aria-label="出貨行"><h2 class="text-h6">出貨行（Base 單位）</h2><DataTable :rows="document.lines" :columns="lineColumns" :initial-pagination="{page:1,rowsPerPage:100}" /></section>
 <section v-else-if="tab==='issues'" aria-label="庫存發出明細"><h2 class="text-h6">庫存發出明細</h2><DataTable :key="`${document.id}:${query.issueAfterId??'0'}`" :rows="document.issues.items" :columns="issueColumns" :initial-pagination="{page:1,rowsPerPage:100}"><template #no-data><p role="status">尚無此頁的庫存發出記錄。</p></template><template #bottom><q-btn flat label="第一頁發出明細" @click="childPage('issueAfterId',null)" /><q-btn flat label="下一頁發出明細" :disable="loading||!document.issues.hasMore" @click="childPage('issueAfterId',document.issues.nextCursor)" /></template></DataTable></section>
 <section v-else aria-label="出貨狀態歷史"><h2 class="text-h6">出貨狀態歷史</h2><DataTable :key="`${document.id}:${query.historyBeforeSequence??'latest'}`" :rows="document.history.items" :columns="historyColumns" row-key="sequence" :initial-pagination="{page:1,rowsPerPage:100}"><template #bottom><q-btn flat label="最新出貨歷史" @click="childPage('historyBeforeSequence',null)" /><q-btn flat label="更早出貨歷史" :disable="loading||!document.history.hasMore" @click="childPage('historyBeforeSequence',document.history.nextCursor)" /></template></DataTable></section>
 <ShipmentFormPanel v-if="document.status==='DRAFT'&&operate" :fulfillment-id="document.fulfillmentId" :customer-id="document.customer.id" :draft="document" :disabled="commands.confirm||commands.cancel||loading||!!error||!document.allowedActions.includes('update')" @permission-lost="error=shipmentFailure({status:403}).message" @dirty="value=>draftDirty=value" @pending="value=>commands.draft=value" @saved="first" />
 <ShipmentConfirmationPanel :document="document" :disabled="draftDirty||commands.draft||commands.cancel||loading||!!error" @permission-lost="error=shipmentFailure({status:403}).message" @pending="value=>commands.confirm=value" @settled="first" />
 <ShipmentCancelPanel :document="document" :disabled="commands.confirm||commands.draft||loading||!!error" @permission-lost="error=shipmentFailure({status:403}).message" @pending="value=>commands.cancel=value" @saved="first" />
 <p v-if="document.status==='CANCELLED'">此草稿已取消，原履約單的實揀工作仍保留；可返回來源履約單建立新出貨草稿。</p>
 </template></section></div></template>
<style scoped>
.shipment-facts { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,240px),1fr)); gap: 16px; }
dt { font-weight: 600; } dd { margin: 0; overflow-wrap: anywhere; }
.shipment-notes { white-space: pre-wrap; overflow-wrap: anywhere; }
</style>
